INSERT INTO homepage_sections (tenant_id, section_type, title, subtitle, content, settings, sort_order, is_visible) VALUES ('cb495693-afce-5116-9e77-8ccd038b2524', 'text_image', 'Getest voor je het koopt', null, '{"text": "We verkopen alleen wat we zelf weken gebruikt hebben. Elk product krijgt een eerlijke beschrijving: wat het goed doet, en wat niet.", "image_url": "", "image_position": "right", "button_text": "Bekijk alles", "button_link": "/producten"}'::jsonb, '{}'::jsonb, 3, true);
INSERT INTO homepage_sections (tenant_id, section_type, title, subtitle, content, settings, sort_order, is_visible) VALUES ('cb495693-afce-5116-9e77-8ccd038b2524', 'faq', 'Goed om te weten', null, '{"items": [{"question": "Hoe lang is de garantie?", "answer": "Twee jaar op alles. Werkt iets niet, dan sturen we meteen een nieuw toestel."}, {"question": "Kan ik retourneren?", "answer": "Ja, binnen 30 dagen, ook als je de doos al geopend hebt."}, {"question": "Is dit een echte winkel?", "answer": "Nee, dit is een demowinkel van SellQo. Je kan alles uitproberen, ook afrekenen, maar er wordt niets verzonden of aangerekend."}]}'::jsonb, '{}'::jsonb, 4, true);